 473→+// Wrap returns the Agent wrapped as an agent.Agent that implements ALL optional
 474→+// interfaces (forwarding to the underlying external agent) plus CapabilityDeclarer.
 475→+// The As* helpers in the agent package use DeclaredCapabilities() to gate access,
 476→+// so callers only see capabilities the external binary actually declared.
 477→+func Wrap(ea *Agent) agent.Agent {
 478→+	caps := ea.info.Capabilities
 479→+	return &wrappedAgent{
 480→+		ea: ea,
 481→+		caps: agent.DeclaredCaps{
 482→+			Hooks:                  caps.Hooks,
 483→+			TranscriptAnalyzer:     caps.TranscriptAnalyzer,
 484→+			TranscriptPreparer:     caps.TranscriptPreparer,
 485→+			TokenCalculator:        caps.TokenCalculator,
 486→+			TextGenerator:          caps.TextGenerator,
 487→+			HookResponseWriter:     caps.HookResponseWriter,
 488→+			SubagentAwareExtractor: caps.SubagentAwareExtractor,
 489→+		},
 490→+	}
 491→+}
