 629→+
 630→+const binaryPrefix = "entire-agent-"
 631→+
 632→+// DiscoverAndRegister scans $PATH for executables matching "entire-agent-<name>",
 633→+// calls their "info" subcommand, and registers them in the agent registry.
 634→+// Binaries whose name conflicts with an already-registered agent are skipped.
 635→+// Errors during discovery are logged but do not prevent other agents from loading.
 636→+func DiscoverAndRegister(ctx context.Context) {
 637→+	if !settings.IsExternalAgentsEnabled(ctx) {
 638→+		logging.Debug(ctx, "external agent discovery disabled (external_agents not enabled in settings)")
 639→+		return
 640→+	}
 641→+
 642→+	pathEnv := os.Getenv("PATH")
 643→+	if pathEnv == "" {
 644→+		return
 645→+	}
 646→+
 647→+	// Collect already-registered names to avoid conflicts.
 648→+	registered := make(map[types.AgentName]bool)
 649→+	for _, name := range agent.List() {
 650→+		registered[name] = true
 651→+	}
 652→+
 653→+	seen := make(map[string]bool) // deduplicate binaries across PATH dirs
 654→+	for _, dir := range filepath.SplitList(pathEnv) {
 655→+		entries, err := os.ReadDir(dir)
 656→+		if err != nil {
 657→+			continue // skip unreadable directories
 658→+		}
 659→+		for _, entry := range entries {
 660→+			name := entry.Name()
 661→+			if !strings.HasPrefix(name, binaryPrefix) {
 662→+				continue
 663→+			}
 664→+			if seen[name] {
 665→+				continue
 666→+			}
 667→+			seen[name] = true
 668→+
 669→+			agentName := types.AgentName(strings.TrimPrefix(name, binaryPrefix))
 670→+			if registered[agentName] {
 671→+				logging.Debug(ctx, "skipping external agent (name conflict with built-in)",
 672→+					slog.String("binary", name),
 673→+					slog.String("agent", string(agentName)))
 674→+				continue
 675→+			}
 676→+
 677→+			binPath := filepath.Join(dir, name)
 678→+			finfo, err := os.Stat(binPath) //nolint:gosec // PATH entries are trusted
 679→+			if err != nil || finfo.IsDir() {
 680→+				continue
 681→+			}
 682→+			// Check executable bit (on Unix)
 683→+			if finfo.Mode()&0o111 == 0 {
 684→+				continue
 685→+			}
 686→+
 687→+			ea, err := New(ctx, binPath)
 688→+			if err != nil {
 689→+				logging.Debug(ctx, "skipping external agent (info failed)",
 690→+					slog.String("binary", binPath),
 691→+					slog.String("error", err.Error()))
 692→+				continue
 693→+			}
 694→+
 695→+			// Wrap with capability interfaces and register
 696→+			wrapped := Wrap(ea)
 697→+			agent.Register(agentName, func() agent.Agent {
 698→+				return wrapped
 699→+			})
 700→+			registered[agentName] = true
 701→+
 702→+			logging.Debug(ctx, "registered external agent",
 703→+				slog.String("name", string(agentName)),
 704→+				slog.String("type", string(ea.Type())),
 705→+				slog.String("binary", binPath))
 706→+		}
 707→+	}
 708→+}
