1024→+// Agent implements agent.Agent by delegating to an external binary.
1025→+// Each method invokes a subcommand on the binary and parses the JSON response.
1026→+type Agent struct {
1027→+	binaryPath string
1028→+	info       *InfoResponse
1029→+}
1030→+
1031→+// New creates an Agent by calling the binary's "info" subcommand
1032→+// to cache its metadata. Returns an error if the binary cannot be invoked or returns
1033→+// invalid/incompatible protocol data. The provided context bounds the "info" call;
1034→+// pass a context with a deadline to limit how long discovery waits for each binary.
1035→+func New(ctx context.Context, binaryPath string) (*Agent, error) {
1036→+	ea := &Agent{binaryPath: binaryPath}
1037→+
1038→+	stdout, err := ea.run(ctx, nil, "info")
1039→+	if err != nil {
1040→+		return nil, fmt.Errorf("info: %w", err)
1041→+	}
1042→+
1043→+	var info InfoResponse
1044→+	if err := json.Unmarshal(stdout, &info); err != nil {
1045→+		return nil, fmt.Errorf("info: invalid JSON: %w", err)
1046→+	}
1047→+
1048→+	if info.ProtocolVersion != ProtocolVersion {
1049→+		return nil, fmt.Errorf("protocol version mismatch: binary reports %d, expected %d",
1050→+			info.ProtocolVersion, ProtocolVersion)
1051→+	}
1052→+
1053→+	ea.info = &info
1054→+	return ea, nil
1055→+}
