1400→+// run executes a subcommand on the external binary and returns stdout bytes.
1401→+// If stdin is non-nil it is piped to the process. On non-zero exit, stderr is
1402→+// included in the returned error.
1403→+func (e *Agent) run(ctx context.Context, stdin []byte, args ...string) ([]byte, error) {
1404→+	// Apply a default timeout when the caller hasn't set a deadline, so a hung
1405→+	// external binary can't block the CLI (or git hooks) indefinitely.
1406→+	if _, ok := ctx.Deadline(); !ok {
1407→+		var cancel context.CancelFunc
1408→+		ctx, cancel = context.WithTimeout(ctx, defaultRunTimeout)
1409→+		defer cancel()
1410→+	}
1411→+	cmd := exec.CommandContext(ctx, e.binaryPath, args...)
1412→+	// Ensure I/O goroutines are released shortly after the process is killed,
1413→+	// so cmd.Run() doesn't block waiting for pipe reads.
1414→+	cmd.WaitDelay = 3 * time.Second
1415→+
1416→+	// Set environment: repo root + protocol version
1417→+	cmd.Env = append(cmd.Environ(),
1418→+		"ENTIRE_PROTOCOL_VERSION="+strconv.Itoa(ProtocolVersion),
1419→+	)
1420→+	if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
1421→+		cmd.Env = append(cmd.Env, "ENTIRE_REPO_ROOT="+repoRoot)
1422→+		cmd.Dir = repoRoot
1423→+	}
1424→+
1425→+	if stdin != nil {
1426→+		cmd.Stdin = bytes.NewReader(stdin)
1427→+	}
1428→+
1429→+	const maxOutputBytes = 10 * 1024 * 1024 // 10 MB
1430→+
1431→+	var stdoutBuf, stderrBuf bytes.Buffer
1432→+	cmd.Stdout = &limitedWriter{buf: &stdoutBuf, limit: maxOutputBytes}
1433→+	cmd.Stderr = &limitedWriter{buf: &stderrBuf, limit: maxOutputBytes}
1434→+
1435→+	if err := cmd.Run(); err != nil {
1436→+		errMsg := strings.TrimSpace(stderrBuf.String())
1437→+		if errMsg != "" {
1438→+			return nil, fmt.Errorf("%s: %s", args[0], errMsg)
1439→+		}
1440→+		return nil, fmt.Errorf("%s: %w", args[0], err)
1441→+	}
1442→+
1443→+	return stdoutBuf.Bytes(), nil
1444→+}
1445→+
1446→+// --- Helpers ---
1447→+
1448→+// limitedWriter wraps a bytes.Buffer and stops writing after limit bytes,
1449→+// preventing unbounded memory growth from external process output.
1450→+type limitedWriter struct {
1451→+	buf   *bytes.Buffer
1452→+	limit int
1453→+}
1454→+
1455→+func (w *limitedWriter) Write(p []byte) (int, error) {
1456→+	remaining := w.limit - w.buf.Len()
1457→+	if remaining <= 0 {
1458→+		return len(p), nil // discard, but report success so the process isn't killed
1459→+	}
1460→+	if len(p) > remaining {
1461→+		p = p[:remaining]
1462→+	}
1463→+	n, err := w.buf.Write(p)
1464→+	if err != nil {
1465→+		return n, fmt.Errorf("writing to limited buffer: %w", err)
1466→+	}
1467→+	return n, nil
1468→+}
