2247→+// InfoResponse is the JSON returned by the "info" subcommand.
2248→+type InfoResponse struct {
2249→+	ProtocolVersion int          `json:"protocol_version"`
2250→+	Name            string       `json:"name"`
2251→+	Type            string       `json:"type"`
2252→+	Description     string       `json:"description"`
2253→+	IsPreview       bool         `json:"is_preview"`
