401→// included in the returned error.
402→func (e *Agent) run(ctx context.Context, stdin []byte, args ...string) ([]byte, error) {
403→	// Apply a default timeout when the caller hasn't set a deadline, so a hung
404→	// external binary can't block the CLI (or git hooks) indefinitely.
405→	if _, ok := ctx.Deadline(); !ok {
406→		var cancel context.CancelFunc
407→		ctx, cancel = context.WithTimeout(ctx, defaultRunTimeout)
408→		defer cancel()
409→	}
410→	cmd := exec.CommandContext(ctx, e.binaryPath, args...)
411→	// Ensure I/O goroutines are released shortly after the process is killed,
412→	// so cmd.Run() doesn't block waiting for pipe reads.
413→	cmd.WaitDelay = 3 * time.Second
414→
415→	// Set environment: repo root + protocol version
416→	cmd.Env = append(cmd.Environ(),
417→		"ENTIRE_PROTOCOL_VERSION="+strconv.Itoa(ProtocolVersion),
418→	)
419→	if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
420→		cmd.Env = append(cmd.Env, "ENTIRE_REPO_ROOT="+repoRoot)
421→		cmd.Dir = repoRoot
422→	}
423→
424→	if stdin != nil {
425→		cmd.Stdin = bytes.NewReader(stdin)
426→	}
427→
428→	const maxOutputBytes = 10 * 1024 * 1024 // 10 MB
429→
430→	var stdoutBuf, stderrBuf bytes.Buffer
431→	cmd.Stdout = &limitedWriter{buf: &stdoutBuf, limit: maxOutputBytes}
432→	cmd.Stderr = &limitedWriter{buf: &stderrBuf, limit: maxOutputBytes}
433→
434→	if err := cmd.Run(); err != nil {
435→		errMsg := strings.TrimSpace(stderrBuf.String())
436→		if errMsg != "" {
437→			return nil, fmt.Errorf("%s: %s", args[0], errMsg)
438→		}
439→		return nil, fmt.Errorf("%s: %w", args[0], err)
440→	}
441→
442→	return stdoutBuf.Bytes(), nil
443→}
